-- Re-runnable: subtopic-scoped DELETE. Run the four batches in any order in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'Acids & Bases' AND subtopic IN ('Titration & Titration Curves', 'Buffers & Henderson-Hasselbalch');

-- Q1 [Titration & Titration Curves · easy · Skill 1 · 5A Titration (GC) · general-chemistry · ans A] (g59)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt59$A \(50.0\ \text{mL}\) sample of \(\text{HCl}\) of unknown concentration is titrated with \(0.100\ \text{M}\) \(\text{NaOH}\) delivered from a buret. The equivalence point of this titration is the moment at which$qt59$,
    $op59$[{"label":"A","text":"the moles of \\(\\text{NaOH}\\) added equal the moles of \\(\\text{HCl}\\) originally present."},{"label":"B","text":"the solution reaches \\(\\text{pH}\\) \\(7\\) regardless of the acid and base involved."},{"label":"C","text":"the indicator first changes color, signaling the buret reading to record."},{"label":"D","text":"the volume of \\(\\text{NaOH}\\) added equals the \\(50.0\\ \\text{mL}\\) volume of the \\(\\text{HCl}\\) sample."}]$op59$::jsonb,
    'A',
    $ex59$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is A because the equivalence point is defined stoichiometrically: it is the point at which the titrant added has supplied an amount of base chemically equivalent to the amount of acid initially present in the titrand. In this acid-base titration, \(\text{NaOH}\) (the titrant of known concentration delivered from the buret) reacts with \(\text{HCl}\) (the analyte) in a \(1{:}1\) ratio, so the equivalence point occurs exactly when \(\text{moles of NaOH added} = \text{moles of HCl originally present}\). This definition is what makes titration a quantitative method, because the known moles of titrant at that point reveal the unknown moles of analyte. (Choice B) A \(\text{pH}\) of \(7\) at the equivalence point holds only for a strong acid titrated with a strong base, where the salt formed does not hydrolyze; for a weak acid or weak base the equivalence-point \(\text{pH}\) is above or below \(7\), so neutral \(\text{pH}\) is not the general defining feature. (Choice C) The indicator color change marks the endpoint, an experimental approximation of the equivalence point chosen so the two nearly coincide; the equivalence point is the underlying stoichiometric condition, not the observed signal. (Choice D) Equal volumes of titrant and analyte coincide with the equivalence point only when their molar concentrations happen to be equal; because the equivalence point depends on equal moles rather than equal volumes, matching the \(50.0\ \text{mL}\) sample volume is generally incorrect. Skill 1$ex59$,
    'easy', '5A', $cc59$Titration (GC)$cc59$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a59B$equivalence-point-always-pH-7$a59B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a59C$endpoint-conflated-with-equivalence-point$a59C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a59D$equal-volumes-mistaken-for-equal-moles$a59D$ FROM q;

-- Q2 [Titration & Titration Curves · easy · Skill 2 · 5A Titration (GC) · general-chemistry · ans B] (g60)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt60$A 40.0 mL sample of 0.100 M \(\text{HCl}\) is titrated with 0.200 M \(\text{NaOH}\). What volume of \(\text{NaOH}\) is required to reach the equivalence point?$qt60$,
    $op60$[{"label":"A","text":"10.0 mL"},{"label":"B","text":"20.0 mL"},{"label":"C","text":"40.0 mL"},{"label":"D","text":"80.0 mL"}]$op60$::jsonb,
    'B',
    $ex60$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is B because at the equivalence point of a monoprotic strong acid–strong base titration the moles of added \(\text{OH}^-\) exactly equal the moles of \(\text{H}^+\) initially present, so \(M_\text{acid}V_\text{acid} = M_\text{base}V_\text{base}\). Compute the moles of acid: \((0.100\ \text{M})(40.0\ \text{mL}) = 4.00\ \text{mmol}\ \text{HCl}\). At equivalence this requires \(4.00\ \text{mmol}\ \text{NaOH}\). Solving for the base volume, \(V_\text{base} = \dfrac{M_\text{acid}V_\text{acid}}{M_\text{base}} = \dfrac{(0.100)(40.0)}{0.200} = 20.0\ \text{mL}\). Because the base is twice as concentrated as the acid, it takes half the acid's volume to neutralize it. (Choice A) 10.0 mL comes from dividing the 20.0 mL result by an extra factor of two, as if the base were four times as concentrated as the acid; only one factor of \(\tfrac{0.200}{0.100} = 2\) applies, giving 20.0 mL, not 10.0 mL. (Choice C) 40.0 mL assumes the equivalence point occurs when equal volumes of acid and base are mixed, which is true only for equal concentrations; here \(M_\text{base} = 0.200\ \text{M} \neq M_\text{acid} = 0.100\ \text{M}\), so equal volumes would deliver twice the needed \(\text{OH}^-\). (Choice D) 80.0 mL comes from inverting the formula and computing \(\dfrac{M_\text{base}V_\text{acid}}{M_\text{acid}} = \dfrac{(0.200)(40.0)}{0.100}\); this misplaces the base molarity in the numerator, whereas the more concentrated base must require a smaller, not larger, volume. Skill 2$ex60$,
    'easy', '5A', $cc60$Titration (GC)$cc60$, 'general-chemistry', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'scale_unit_error', $a60A$Applied an extra factor-of-two division, treating the concentration ratio as 4 instead of 2$a60A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a60C$Assumed equivalence occurs at equal volumes, ignoring the unequal concentrations$a60C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a60D$Inverted the dilution formula, placing base molarity in the numerator so the more concentrated base appears to need more volume$a60D$ FROM q;

-- Q3 [Titration & Titration Curves · easy · Skill 2 · 5A Titration (GC) · general-chemistry · ans C] (g61)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt61$A 25.00 mL sample of 0.0500 M acetic acid, a monoprotic acid, is titrated with a strong base until it reaches the equivalence point. How many moles of strong base have been added at the equivalence point?$qt61$,
    $op61$[{"label":"A","text":"\\(1.25\\,\\text{mol}\\)"},{"label":"B","text":"\\(2.50\\times10^{-3}\\,\\text{mol}\\)"},{"label":"C","text":"\\(1.25\\times10^{-3}\\,\\text{mol}\\)"},{"label":"D","text":"\\(6.25\\times10^{-4}\\,\\text{mol}\\)"}]$op61$::jsonb,
    'C',
    $ex61$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is C because at the equivalence point the moles of strong base added exactly equal the moles of acid originally present, and the acid is monoprotic so each mole of acid neutralizes one mole of base. First convert the analyte volume from milliliters to liters: \(25.00\,\text{mL} = 0.02500\,\text{L}\). Then moles of acetic acid \(= M \times V = (0.0500\,\text{mol/L})(0.02500\,\text{L}) = 1.25\times10^{-3}\,\text{mol}\). Because the equivalence point is defined by \(\text{moles base} = \text{moles acid}\) for a 1:1 monoprotic neutralization, the base added equals \(1.25\times10^{-3}\,\text{mol}\). (Choice A) \(1.25\,\text{mol}\) results from multiplying \(0.0500\) by \(25.00\) without converting milliliters to liters, inflating the answer by a factor of 1000. (Choice B) \(2.50\times10^{-3}\,\text{mol}\) results from doubling the moles of acid as if a second equivalent of base were required, which would only apply to a diprotic acid, not a monoprotic acid like acetic acid. (Choice D) \(6.25\times10^{-4}\,\text{mol}\) results from incorrectly halving the moles of acid, as if the equivalence point were reached after adding only half an equivalent of base. Skill 2$ex61$,
    'easy', '5A', $cc61$Titration (GC)$cc61$, 'general-chemistry', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'scale_unit_error', $a61A$Multiplied molarity by volume in mL without converting to L, off by 1000$a61A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a61B$Treated monoprotic acid as diprotic and doubled the required moles of base$a61B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a61D$Halved the moles of acid, as if equivalence occurs at half-neutralization$a61D$ FROM q;

-- Q4 [Titration & Titration Curves · easy · Skill 1 · 5A Titration (GC) · general-chemistry · ans D] (g62)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt62$A 25.0 mL sample of 0.100 M HCl is titrated with 0.100 M NaOH at 25 °C. What is the pH of the solution at the equivalence point, where exactly 25.0 mL of titrant has been added?$qt62$,
    $op62$[{"label":"A","text":"\\(\\text{pH} = 1.00\\)"},{"label":"B","text":"\\(\\text{pH} = 4.00\\)"},{"label":"C","text":"\\(\\text{pH} = 13.00\\)"},{"label":"D","text":"\\(\\text{pH} = 7.00\\)"}]$op62$::jsonb,
    'D',
    $ex62$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is D because the equivalence point of a strong acid–strong base titration is exactly neutral at 25 °C. At the equivalence point the moles of \(\text{NaOH}\) added equal the moles of \(\text{HCl}\) present: \((0.100\ \text{M})(0.0250\ \text{L}) = 2.50 \times 10^{-3}\ \text{mol}\) of each, so all \(\text{HCl}\) is consumed and neither acid nor base is in excess. The only species remaining besides water is the salt \(\text{NaCl}\). Because \(\text{Na}^+\) is the cation of a strong base and \(\text{Cl}^-\) is the anion of a strong acid, neither ion hydrolyzes, so the salt is pH-neutral and the pH is fixed solely by water autoionization: \([\text{H}^+] = [\text{OH}^-] = 1.0 \times 10^{-7}\ \text{M}\), giving \(\text{pH} = -\log(1.0 \times 10^{-7}) = 7.00\). (Choice A) \(\text{pH} = 1.00\) is \(-\log(0.100)\), the pH of the original \(\text{HCl}\) before any base is added; it ignores that the titration has reached the equivalence point and the acid has been fully neutralized. (Choice B) \(\text{pH} = 4.00\) assumes the salt hydrolyzes to give an acidic solution, but \(\text{Cl}^-\) is the conjugate base of a strong acid and is far too weak to hydrolyze, so no acidity is generated. (Choice C) \(\text{pH} = 13.00\) treats the titrant base as if it were in excess, computing \(\text{pOH} = -\log(0.100) = 1.00\) and \(\text{pH} = 14.00 - 1.00 = 13.00\); at the exact equivalence point, however, the base is not in excess—stoichiometric amounts have reacted. Skill 1$ex62$,
    'easy', '5A', $cc62$Titration (GC)$cc62$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a62A$Reports the initial pH of the analyte acid (\(-\log 0.100 = 1.00\)) instead of the equivalence-point pH$a62A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a62B$Believes the spectator salt NaCl undergoes hydrolysis to produce an acidic solution$a62B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a62C$Treats the strong-base titrant as being in excess at the equivalence point, yielding a strongly basic pH$a62C$ FROM q;

-- Q5 [Titration & Titration Curves · medium · Skill 4 · 5A Titration (GC) · general-chemistry · ans A] (g63)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt63$Two monoprotic weak acids of equal concentration are each titrated with \( \text{NaOH} \) of the same concentration, and their titration curves are recorded: \( \text{HA} \) has \( K_a = 1\times10^{-5} \), and \( \text{HB} \) has \( K_a = 1\times10^{-3} \). Which titration shows the larger, sharper vertical \( \text{pH} \) jump in the region surrounding its equivalence point, and why?$qt63$,
    $op63$[{"label":"A","text":"The titration of \\( \\text{HB} \\), because its buffer plateau just before equivalence sits at a lower \\( \\text{pH} \\) while the \\( \\text{pH} \\) just past equivalence is set by the same excess strong base, so the vertical rise spans a wider \\( \\text{pH} \\) range."},{"label":"B","text":"The titration of \\( \\text{HA} \\), because its buffer plateau just before equivalence sits at a lower \\( \\text{pH} \\) while the \\( \\text{pH} \\) just past equivalence is set by the same excess strong base, so the vertical rise spans a wider \\( \\text{pH} \\) range."},{"label":"C","text":"Neither; both curves show the same size of jump, because just past the equivalence point each solution contains the same excess of strong base and reaches the same \\( \\text{pH} \\)."},{"label":"D","text":"Neither; both curves show the same size of jump, because the magnitude of the jump is fixed by the concentrations of acid and titrant and does not depend on the acid's \\( K_a \\)."}]$op63$::jsonb,
    'A',
    $ex63$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is A because the size of the steep jump near the equivalence point is the difference between the \( \text{pH} \) just before equivalence and the \( \text{pH} \) just after it. Just before equivalence the solution is a buffer whose \( \text{pH} \) tracks the acid's \( \text{p}K_a \): the stronger acid \( \text{HB} \) (larger \( K_a \), so lower \( \text{p}K_a \)) holds its buffer plateau at a lower \( \text{pH} \) than the weaker acid \( \text{HA} \). Just after equivalence, the \( \text{pH} \) of both solutions is governed by the same small excess of identical strong base, so both rise to essentially the same high \( \text{pH} \). Because \( \text{HB} \) starts the climb from a lower buffer \( \text{pH} \) and ends at the same point, its vertical jump spans a wider \( \text{pH} \) range and is sharper; \( \text{HA} \)'s plateau lies closer to its endpoint, so its jump is smaller and more gradual. (Choice B) reverses the relationship: the weaker acid \( \text{HA} \) has the higher buffer plateau, so its climb to the common post-equivalence \( \text{pH} \) is shorter, giving the smaller jump rather than the larger one. (Choice C) correctly notes that the post-equivalence \( \text{pH} \) is the same for both, but it ignores the pre-equivalence buffer level, which differs with \( \text{p}K_a \); equal endpoints with different starting plateaus give jumps of different size. (Choice D) is wrong because the jump magnitude does depend on \( K_a \): for fixed concentrations, the buffer \( \text{pH} \) just before equivalence is set by \( \text{p}K_a \), so two acids of different \( K_a \) produce jumps of different size. Skill 4$ex63$,
    'medium', '5A', $cc63$Titration (GC)$cc63$, 'general-chemistry', 4, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a63B$weaker acid wrongly assigned the larger/sharper equivalence-point jump$a63B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a63C$correct that post-equivalence pH matches but ignores the differing pre-equivalence buffer plateau$a63C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a63D$believes the jump magnitude depends only on concentration and is independent of Ka$a63D$ FROM q;

-- Q6 [Titration & Titration Curves · medium · Skill 4 · 5A Titration (GC) · general-chemistry · ans D] (g64)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt64$A \(25.0\,\text{mL}\) sample of \(0.10\,\text{M}\) aqueous ammonia (a weak base) and a separate \(25.0\,\text{mL}\) sample of \(0.10\,\text{M}\) \(\text{NaOH}\) (a strong base) are each titrated with the same \(0.10\,\text{M}\) \(\text{HCl}\) solution. How do the volumes of \(\text{HCl}\) required to reach the equivalence point in the two titrations compare?$qt64$,
    $op64$[{"label":"A","text":"The volumes cannot be compared without knowing the \\(K_b\\) of ammonia, since the strength of the base sets the amount of titrant needed."},{"label":"B","text":"The ammonia sample requires less \\(\\text{HCl}\\), because as a weak base it is only partially ionized and so presents fewer moles to neutralize."},{"label":"C","text":"The ammonia sample requires more \\(\\text{HCl}\\), because additional titrant is needed to drive the incomplete ionization of the weak base to completion."},{"label":"D","text":"The volumes are equal, because reaching the equivalence point depends only on the stoichiometric mole ratio of acid to base, not on the strength of the base."}]$op64$::jsonb,
    'D',
    $ex64$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is D because the equivalence point is reached when the moles of added acid equal the moles of base originally present, and that mole count is fixed entirely by the stoichiometry of the samples. Each sample contains \((0.0250\,\text{L})(0.10\,\text{M}) = 2.5\times10^{-3}\,\text{mol}\) of base, so each requires \(2.5\times10^{-3}\,\text{mol}\) of \(\text{HCl}\), which at \(0.10\,\text{M}\) is exactly \(25.0\,\text{mL}\) in both cases. The strength of the base governs the pH at the equivalence point (the ammonia titration gives an acidic equivalence point because \(\text{NH}_4^+\) remains, while the \(\text{NaOH}\) titration gives a neutral one), but it does not change the volume of titrant needed to get there. (Choice A) The \(K_b\) value affects only the pH profile of the curve and the pH at equivalence, not the equivalence volume, which is determined solely by the moles of base present. (Choice B) This reflects the common misconception that partial ionization reduces the moles available to react; in fact, as protons are removed by the acid, the equilibrium continually replenishes the reactive base, so the full \(2.5\times10^{-3}\,\text{mol}\) is ultimately neutralized. (Choice C) This is the opposite misconception, assuming extra titrant is consumed to overcome incomplete ionization, but the stoichiometric mole ratio—not the rate or extent of ionization—sets the endpoint volume. Skill 4$ex64$,
    'medium', '5A', $cc64$Titration (GC)$cc64$, 'general-chemistry', 4, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a64A$equivalence volume cannot be found without Kb because strength sets titrant amount$a64A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a64B$weak base is only partially ionized so fewer moles need neutralizing$a64B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a64C$extra titrant needed to drive incomplete weak-base ionization to completion$a64C$ FROM q;

-- Q7 [Titration & Titration Curves · hard · Skill 2 · 5A Titration (GC) · general-chemistry · ans C] (g65)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt65$A \(25.00\,\text{mL}\) sample of \(0.100\,\text{M}\) \(\text{HCl}\) is titrated with \(0.100\,\text{M}\) \(\text{NaOH}\). After exactly \(12.50\,\text{mL}\) of the \(\text{NaOH}\) has been added (before the equivalence point), what is the \(\text{pH}\) of the solution? Both species are strong, so treat the neutralization as complete.$qt65$,
    $op65$[{"label":"A","text":"\\(\\text{pH} = 1.30\\)"},{"label":"B","text":"\\(\\text{pH} = 1.18\\)"},{"label":"C","text":"\\(\\text{pH} = 1.48\\)"},{"label":"D","text":"\\(\\text{pH} = 7.00\\)"}]$op65$::jsonb,
    'C',
    $ex65$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is C because at a pre-equivalence point in a strong acid-strong base titration the \(\text{pH}\) is set by the leftover excess strong acid, whose concentration must be computed using the total combined volume. First find the moles present: \(\text{HCl} = 0.02500\,\text{L} \times 0.100\,\text{M} = 2.50\times10^{-3}\,\text{mol}\) and \(\text{NaOH} = 0.01250\,\text{L} \times 0.100\,\text{M} = 1.25\times10^{-3}\,\text{mol}\). The added \(\text{OH}^-\) neutralizes an equal amount of \(\text{H}^+\), leaving excess \(\text{H}^+ = 2.50\times10^{-3} - 1.25\times10^{-3} = 1.25\times10^{-3}\,\text{mol}\). The total volume is now \(25.00 + 12.50 = 37.50\,\text{mL} = 0.03750\,\text{L}\), so \([\text{H}^+] = \dfrac{1.25\times10^{-3}}{0.03750} = 0.0333\,\text{M}\). Then \(\text{pH} = -\log(0.0333) = 1.48\). (Choice A) \(\text{pH} = 1.30\) comes from dividing the excess \(1.25\times10^{-3}\,\text{mol}\) of \(\text{H}^+\) by the original acid volume \(0.02500\,\text{L}\) to get \(0.0500\,\text{M}\); this ignores that the added base volume dilutes the solution, so the total volume \(0.03750\,\text{L}\) must be used. (Choice B) \(\text{pH} = 1.18\) comes from dividing the original \(2.50\times10^{-3}\,\text{mol}\) of \(\text{H}^+\) by the total volume \(0.03750\,\text{L}\) to get \(0.0667\,\text{M}\); this fails to subtract the moles of acid neutralized by the added base before computing the concentration. (Choice D) \(\text{pH} = 7.00\) treats the solution as if it had reached the equivalence point where strong acid and strong base exactly cancel to give a neutral salt solution, but only half of the acid has been neutralized at \(12.50\,\text{mL}\), so excess acid remains and the \(\text{pH}\) is well below \(7\). Skill 2$ex65$,
    'hard', '5A', $cc65$Titration (GC)$cc65$, 'general-chemistry', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
