UNION ALL SELECT id, 'B', 'process_step_confusion', $a65B$divides the original (un-neutralized) moles of acid by the total volume, failing to subtract the H+ consumed by the added OH-$a65B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a65D$assumes the pre-equivalence point is the equivalence point and reports a neutral pH of 7 for the strong acid-strong base mixture$a65D$ FROM q;

-- Q8 [Titration & Titration Curves · hard · Skill 2 · 5A Titration (GC) · general-chemistry · ans D] (g66)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt66$A 25.00 mL sample of 0.100 M \(\text{HCl}\) is titrated with 0.100 M \(\text{NaOH}\). After a total of 37.50 mL of titrant has been delivered — 12.50 mL beyond the equivalence point — what is the \(\text{pH}\) of the resulting solution at 25 °C?$qt66$,
    $op66$[{"label":"A","text":"\\(\\text{pH} = 1.70\\)"},{"label":"B","text":"\\(\\text{pH} = 12.78\\)"},{"label":"C","text":"\\(\\text{pH} = 13.00\\)"},{"label":"D","text":"\\(\\text{pH} = 12.30\\)"}]$op66$::jsonb,
    'D',
    $ex66$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is D because the strong-base titrant is in excess past the equivalence point, so the leftover \(\text{OH}^-\) sets the \(\text{pH}\). Initial acid: \(25.00\,\text{mL} \times 0.100\,\text{M} = 2.500\,\text{mmol}\ \text{H}^+\). Titrant added: \(37.50\,\text{mL} \times 0.100\,\text{M} = 3.750\,\text{mmol}\ \text{OH}^-\). The first \(2.500\,\text{mmol}\ \text{OH}^-\) neutralizes all the \(\text{H}^+\) (equivalence at 25.00 mL), leaving excess \(\text{OH}^-\) of \(3.750 - 2.500 = 1.250\,\text{mmol}\). The total volume is \(25.00 + 37.50 = 62.50\,\text{mL}\), so \([\text{OH}^-] = 1.250\,\text{mmol} / 62.50\,\text{mL} = 0.0200\,\text{M}\). Then \(\text{pOH} = -\log(0.0200) = 1.70\), and \(\text{pH} = 14.00 - 1.70 = 12.30\). (Choice A) \(1.70\) is the \(\text{pOH}\) of the solution reported as if it were the \(\text{pH}\); past the equivalence point the solution is strongly basic, so \(\text{pH} = 14.00 - \text{pOH} = 12.30\), not the \(\text{pOH}\) value itself. (Choice B) \(12.78\) results from dividing the total titrant (\(3.750\,\text{mmol}\)) by 62.50 mL to get \([\text{OH}^-] = 0.0600\,\text{M}\), failing to subtract the \(2.500\,\text{mmol}\) consumed in neutralizing the acid. (Choice C) \(13.00\) comes from dividing the correct excess \(1.250\,\text{mmol}\) by only the 12.50 mL added past equivalence rather than the full 62.50 mL solution volume, giving \(0.100\,\text{M}\) instead of \(0.0200\,\text{M}\). Skill 2$ex66$,
    'hard', '5A', $cc66$Titration (GC)$cc66$, 'general-chemistry', 2, 160
  ) RETURNING id
)
