-- Q12 [Titration & Titration Curves · medium · Skill 4 · 5A Titration (GC) · general-chemistry · ans B] (g70)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt70$A \(0.10\ \text{M}\) solution of the weak acid propanoic acid is titrated with \(0.10\ \text{M}\ \text{NaOH}\), and the equivalence point falls at \(\text{pH}\) near \(9\). An indicator changes color over the interval \(\text{p}K_{a(\text{In})} \pm 1\). Which indicator's transition range correctly brackets this equivalence point so the color change signals it?$qt70$,
    $op70$[{"label":"A","text":"Methyl orange, transition range \\(\\text{pH}\\ 3.2\\text{–}4.4\\)"},{"label":"B","text":"Phenolphthalein, transition range \\(\\text{pH}\\ 8.3\\text{–}10.0\\)"},{"label":"C","text":"Bromothymol blue, transition range \\(\\text{pH}\\ 6.0\\text{–}7.6\\)"},{"label":"D","text":"Methyl red, transition range \\(\\text{pH}\\ 4.4\\text{–}6.2\\)"}]$op70$::jsonb,
    'B',
    $ex70$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is B because the indicator's color-change interval must bracket the equivalence-point \(\text{pH}\), and only phenolphthalein's range of \(\text{pH}\ 8.3\text{–}10.0\) contains the equivalence point near \(\text{pH}\ 9\). An acid–base indicator is itself a weak acid \(\text{HIn}\) whose protonated and deprotonated conjugate forms differ in color; the visible color shifts over roughly \(\text{p}K_{a(\text{In})} \pm 1\), so a phenolphthalein \(\text{p}K_{a(\text{In})}\) near \(9\) gives a transition centered on the equivalence \(\text{pH}\). A weak acid titrated with a strong base yields a basic equivalence point because the conjugate base remaining in solution hydrolyzes, so the steep portion of the curve passes through \(\text{pH}\ 9\), where the \(8.3\text{–}10.0\) window sits squarely on the vertical region and changes color sharply. (Choice A) Methyl orange transitions at \(\text{pH}\ 3.2\text{–}4.4\), well below the equivalence point; it would change color early on the slowly rising buffer region and never bracket \(\text{pH}\ 9\). (Choice C) Bromothymol blue spans \(\text{pH}\ 6.0\text{–}7.6\), appropriate for a strong-acid–strong-base titration that equilibrates near \(\text{pH}\ 7\), but it lies below the basic equivalence point of this weak-acid system. (Choice D) Methyl red transitions at \(\text{pH}\ 4.4\text{–}6.2\), which brackets the half-equivalence buffer region near the acid's \(\text{p}K_a\) rather than the equivalence point, so it would change color far too soon. Skill 4$ex70$,
    'medium', '5A', $cc70$Titration (GC)$cc70$, 'general-chemistry', 4, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a70A$Selects a real indicator whose acidic-range transition fits a strong-acid endpoint, not the basic weak-acid equivalence point$a70A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a70C$Assumes every equivalence point occurs at neutral pH 7 and picks the indicator centered there$a70C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a70D$Confuses the half-equivalence (pH = pKa buffer) region with the equivalence point and matches the indicator to the wrong curve feature$a70D$ FROM q;

-- Q13 [Titration & Titration Curves · hard · Skill 4 · 5A Titration (GC) · general-chemistry · ans A] (g71)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Titration & Titration Curves',
    $qt71$A chemist titrates the diprotic acid malonic acid (\(\text{p}K_{a1}=2.8\), \(\text{p}K_{a2}=5.7\)) with standardized \(\text{NaOH}\) and selects an indicator whose color change is centered on the steep portion of the second jump. The recorded titration curve starts near \(\text{pH}\) 2, rises through a half-equivalence plateau near \(\text{pH}\) 2.8, climbs to a first steep rise, levels off again near \(\text{pH}\) 5.7, then rises steeply a second time. Which statement correctly distinguishes the endpoint from the equivalence point and accounts for the two plateaus on this curve?$qt71$,
    $op71$[{"label":"A","text":"The equivalence point is where stoichiometrically equal moles of base have neutralized the acid, while the endpoint is the observed indicator color change; the two plateaus are buffer regions, one centered near each \\(\\text{p}K_a\\), reflecting the two stepwise deprotonations."},{"label":"B","text":"The endpoint is where stoichiometrically equal moles have reacted, while the equivalence point is the observed indicator color change; the two plateaus are the two equivalence points, one at each \\(\\text{p}K_a\\)."},{"label":"C","text":"The equivalence point and the endpoint are identical by definition, so the two plateaus simply mark where the indicator changes color twice as each proton is removed."},{"label":"D","text":"The equivalence point is the observed indicator color change, while the endpoint is the steep vertical region; the two plateaus are the first and second equivalence points where \\(\\text{pH}=\\text{p}K_a\\)."}]$op71$::jsonb,
    'A',
    $ex71$This is a General Chemistry question that falls under the content category 'Titration (GC)'. The answer to this question is A because the equivalence point is a stoichiometric quantity defined by equal moles of titrant and analyte having reacted, whereas the endpoint is the experimentally observed signal (the indicator color change); a well-chosen indicator merely makes the endpoint fall close to the equivalence point but does not make them the same thing. For malonic acid, a diprotic acid, neutralization proceeds in two stepwise stages, so the described curve shows two steep rises (two equivalence points) separated by two flat buffer regions. Each plateau is a half-equivalence region in which a weak acid and its conjugate base coexist; by Henderson-Hasselbalch \(\text{pH}=\text{p}K_a+\log\left(\dfrac{[\text{A}^-]}{[\text{HA}]}\right)\), the midpoint of each plateau occurs where \([\text{A}^-]=[\text{HA}]\) and \(\text{pH}=\text{p}K_a\), giving plateaus centered near \(\text{pH}\) 2.8 and \(\text{pH}\) 5.7. Thus the flat regions are buffer regions tied to the two \(\text{p}K_a\) values, not the equivalence points themselves. (Choice B) This reverses the definitions: the equivalence point is the stoichiometric quantity and the endpoint is the indicator-based observation, not the other way around; it also misidentifies the flat plateaus as the equivalence points, when equivalence points lie on the steep rises. (Choice C) The equivalence point and endpoint are not identical by definition; they are conceptually distinct and only approximately coincide when the indicator is well chosen, and the plateaus are buffer regions rather than points of color change. (Choice D) This again swaps the two definitions and incorrectly places \(\text{pH}=\text{p}K_a\) at the equivalence points; \(\text{pH}=\text{p}K_a\) holds at the half-equivalence midpoints of the buffer plateaus, while the equivalence points sit on the steep portions of the curve. Skill 1$ex71$,
    'hard', '5A', $cc71$Titration (GC)$cc71$, 'general-chemistry', 4, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
