UNION ALL SELECT id, 'C', 'misconception', $a71C$endpoint and equivalence point treated as identical by definition$a71C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a71D$pH=pKa misplaced at equivalence point instead of half-equivalence$a71D$ FROM q;

-- Q14 [Buffers & Henderson-Hasselbalch · easy · Skill 1 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans A] (g72)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Buffers & Henderson-Hasselbalch',
    $qt72$A student wants to prepare a beaker of solution that resists a change in \(\text{pH}\) when small amounts of acid or base are added. To build this buffer, which pair of solutes, both present in appreciable amounts, should be combined in the water?$qt72$,
    $op72$[{"label":"A","text":"A weak acid together with its conjugate base, such as \\(\\text{CH}_3\\text{COOH}\\) and \\(\\text{CH}_3\\text{COO}^-\\)"},{"label":"B","text":"A strong acid together with its conjugate base, such as \\(\\text{HCl}\\) and \\(\\text{Cl}^-\\)"},{"label":"C","text":"Two strong acids, such as \\(\\text{HCl}\\) and \\(\\text{HNO}_3\\)"},{"label":"D","text":"A weak acid and a strong base mixed in equal (stoichiometric) amounts, such as \\(\\text{CH}_3\\text{COOH}\\) and \\(\\text{NaOH}\\)"}]$op72$::jsonb,
    'A',
    $ex72$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is A because a buffer is composed of a weak acid together with its conjugate base (or a weak base together with its conjugate acid), both present in appreciable amounts. The weak acid \(\text{CH}_3\text{COOH}\) neutralizes added base, while its conjugate base \([\text{CH}_3\text{COO}^-]\) neutralizes added acid; because the conjugate pair interconverts through the equilibrium \(\text{CH}_3\text{COOH} \rightleftharpoons \text{H}^+ + \text{CH}_3\text{COO}^-\), the ratio \([\text{A}^-]/[\text{HA}]\) shifts only slightly and the \(\text{pH}\) stays near \(\text{p}K_a\), as expressed by the Henderson-Hasselbalch relation \(\text{pH} = \text{p}K_a + \log\frac{[\text{A}^-]}{[\text{HA}]}\). (Choice B) A strong acid such as \(\text{HCl}\) ionizes essentially completely, so its conjugate base \(\text{Cl}^-\) is an exceedingly weak base that does not appreciably accept protons; there is no reservoir of un-ionized acid and no working equilibrium, so the pair cannot resist \(\text{pH}\) change. (Choice C) Two strong acids supply only \(\text{H}^+\) and provide no conjugate base reservoir to neutralize added acid, so the mixture is simply a strongly acidic solution rather than a buffer. (Choice D) Combining a weak acid with a strong base in equal stoichiometric amounts runs the neutralization to completion, consuming essentially all of the \(\text{CH}_3\text{COOH}\) and leaving only \(\text{CH}_3\text{COO}^-\); with the weak-acid component gone, no conjugate pair remains and the solution has no buffering capacity (a buffer requires a sub-stoichiometric amount of strong base so that both species coexist). Skill 1$ex72$,
    'easy', '5A', $cc72$Acid-Base Equilibria (GC, BC)$cc72$, 'general-chemistry', 1, 75
  ) RETURNING id
)
