-- Q15 [Buffers & Henderson-Hasselbalch · medium · Skill 2 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans B] (g73)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Buffers & Henderson-Hasselbalch',
    $qt73$An acetic-acid/acetate buffer is prepared containing \(0.30\ \text{M}\ \text{CH}_3\text{COOH}\) and \(0.030\ \text{M}\ \text{CH}_3\text{COO}^-\), where acetic acid has \(\text{p}K_a = 4.74\). What is the \(\text{pH}\) of this buffer?$qt73$,
    $op73$[{"label":"A","text":"\\(\\text{pH} = 4.74\\)"},{"label":"B","text":"\\(\\text{pH} = 3.74\\)"},{"label":"C","text":"\\(\\text{pH} = 5.74\\)"},{"label":"D","text":"\\(\\text{pH} = 4.04\\)"}]$op73$::jsonb,
    'B',
    $ex73$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is B because the Henderson-Hasselbalch equation, \(\text{pH} = \text{p}K_a + \log\frac{[\text{A}^-]}{[\text{HA}]}\), gives \(\text{pH} = 4.74 + \log\frac{0.030}{0.30} = 4.74 + \log(0.10) = 4.74 + (-1.00) = 3.74\). Because the conjugate base \(\text{CH}_3\text{COO}^-\) is present at one-tenth the concentration of the acid \(\text{CH}_3\text{COOH}\), the buffer sits one \(\log\) unit below \(\text{p}K_a\), making it more acidic than the half-neutralized point. (Choice A) \(\text{pH} = 4.74\) results from dropping the \(\log\) term entirely and equating \(\text{pH}\) to \(\text{p}K_a\); that equality only holds when \([\text{A}^-] = [\text{HA}]\), which is not the case here since the ratio is \(0.10\), not \(1\). (Choice C) \(\text{pH} = 5.74\) comes from a sign error, adding \(1.00\) to \(\text{p}K_a\) instead of subtracting; this would correspond to \([\text{A}^-]\) being ten times the acid, the reverse of the given ratio. (Choice D) \(\text{pH} = 4.04\) reflects an arithmetic slip in evaluating the logarithm (treating \(\log(0.10)\) as roughly \(-0.70\) rather than exactly \(-1.00\)); \(\log(0.10)\) equals \(-1.00\) because \(0.10 = 10^{-1}\). Skill 2$ex73$,
    'medium', '5A', $cc73$Acid-Base Equilibria (GC, BC)$cc73$, 'general-chemistry', 2, 110
  ) RETURNING id
)
