-- Q23 [Buffers & Henderson-Hasselbalch · hard · Skill 2 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans C] (g81)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Buffers & Henderson-Hasselbalch',
    $qt81$A lactic-acid/lactate buffer is prepared so that \([\text{lactate}] = 0.080\ \text{M}\) and \([\text{lactic acid}] = 0.020\ \text{M}\), where lactic acid has \(\text{p}K_a = 3.86\). What is the \(\text{pH}\) of this buffer?$qt81$,
    $op81$[{"label":"A","text":"\\(\\text{pH} = 3.86\\)"},{"label":"B","text":"\\(\\text{pH} = 3.26\\)"},{"label":"C","text":"\\(\\text{pH} = 4.46\\)"},{"label":"D","text":"\\(\\text{pH} = 4.86\\)"}]$op81$::jsonb,
    'C',
    $ex81$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is C because the Henderson-Hasselbalch equation, \(\text{pH} = \text{p}K_a + \log\frac{[\text{A}^-]}{[\text{HA}]}\), accounts for the excess of conjugate base over weak acid. Substituting the given values, \(\text{pH} = 3.86 + \log\frac{0.080}{0.020} = 3.86 + \log(4)\). Since \(\log(4) = 0.60\), the result is \(\text{pH} = 3.86 + 0.60 = 4.46\). Because the conjugate base lactate outnumbers the acid 4-to-1, the buffer sits above its \(\text{p}K_a\), consistent with a solution that is more basic than the point of equal concentrations. (Choice A) \(\text{pH} = 3.86\) ignores the concentration ratio entirely, treating the \(\log\) term as zero; this is only correct when \([\text{A}^-] = [\text{HA}]\), which is not the case here. (Choice B) \(\text{pH} = 3.26\) inverts the ratio, computing \(3.86 + \log\frac{0.020}{0.080} = 3.86 + \log(0.25) = 3.86 - 0.60\); placing the acid over the base wrongly drives the \(\text{pH}\) below the \(\text{p}K_a\). (Choice D) \(\text{pH} = 4.86\) takes \(\log\) of the wrong number, using \(\log(10) = 1\) so that \(3.86 + 1.00 = 4.86\); the true ratio is \(4\), not \(10\), so the \(\log\) term is \(0.60\), not \(1.00\). Skill 2$ex81$,
    'hard', '5A', $cc81$Acid-Base Equilibria (GC, BC)$cc81$, 'general-chemistry', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a81A$Ignores the concentration ratio and equates pH to pKa, assuming the log term is always zero$a81A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a81B$Inverts the base/acid ratio in the log term, putting acid over conjugate base$a81B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a81D$Uses log(10)=1 instead of log(4)=0.60, miscomputing the logarithm of the ratio$a81D$ FROM q;

-- Q24 [Buffers & Henderson-Hasselbalch · medium · Skill 4 · 5A Acid-Base Equilibria (GC, BC) · general-chemistry · ans C] (g82)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Acids & Bases', 'Buffers & Henderson-Hasselbalch',
    $qt82$A chemist prepares an acetate buffer in which \([\text{CH}_3\text{COOH}]\) and \([\text{CH}_3\text{COO}^-]\) are present in equal concentration. The chemist then transfers the buffer to a larger flask and adds pure water until the total volume is ten times its original value, diluting the solution tenfold. Assuming the temperature is held constant and that activity effects are negligible, what happens to the \(\text{pH}\) of the buffer, and why?$qt82$,
    $op82$[{"label":"A","text":"The \\(\\text{pH}\\) change cannot be predicted without knowing the absolute concentrations of \\(\\text{CH}_3\\text{COOH}\\) and \\(\\text{CH}_3\\text{COO}^-\\), not merely their ratio."},{"label":"B","text":"The \\(\\text{pH}\\) rises toward 7, because diluting any aqueous solution with water moves it closer to the neutral value."},{"label":"C","text":"The \\(\\text{pH}\\) stays essentially unchanged, because the Henderson–Hasselbalch \\(\\text{pH}\\) depends on the ratio \\([\\text{A}^-]/[\\text{HA}]\\), and dilution lowers both concentrations by the same factor, leaving that ratio unchanged."},{"label":"D","text":"The \\(\\text{pH}\\) rises by about 1 unit, because a tenfold dilution lowers the hydrogen-ion concentration by a factor of ten, just as it does for a strong acid."}]$op82$::jsonb,
    'C',
    $ex82$This is a General Chemistry question that falls under the content category 'Acid-Base Equilibria (GC, BC)'. The answer to this question is C because the pH of a buffer is governed by the Henderson–Hasselbalch relation \(\text{pH} = \text{p}K_a + \log\frac{[\text{A}^-]}{[\text{HA}]}\), which depends only on the RATIO of conjugate base to weak acid, not on their absolute concentrations. Adding water dilutes both \(\text{CH}_3\text{COOH}\) and \(\text{CH}_3\text{COO}^-\) by the identical factor of ten, so the ratio \([\text{A}^-]/[\text{HA}]\) is preserved (here it stays at 1), the logarithm stays at 0, and the pH remains equal to \(\text{p}K_a\). Hence the pH is essentially unchanged by dilution. (Choice A) The Henderson–Hasselbalch pH depends only on the ratio \([\text{A}^-]/[\text{HA}]\), which here is fixed at 1:1 and is unchanged by dilution; the absolute concentrations are not needed to conclude that the pH stays essentially constant, so claiming the change is unpredictable without them is incorrect. (Choice B) The notion that any dilution drives a solution toward neutral pH 7 is a misconception; it holds only as a limiting tendency for extreme dilution of dilute non-buffered solutions, and a buffer specifically resists this because its conjugate ratio, not its absolute concentration, fixes the pH. (Choice D) A strong, fully ionized acid does have its pH rise by about one unit per tenfold dilution, because its \([\text{H}_3\text{O}^+]\) falls in step with its concentration, but a buffer is not a strong acid; equating the two confuses the strong-acid concentration dependence with the buffer's ratio dependence, so the predicted one-unit shift does not occur. Skill 4$ex82$,
    'medium', '5A', $cc82$Acid-Base Equilibria (GC, BC)$cc82$, 'general-chemistry', 4, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
