UNION ALL SELECT id, 'B', 'misconception', $a82B$dilution drives all solutions toward neutral pH 7$a82B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a82D$applies the strong-acid one-pH-unit-per-tenfold-dilution rule to a buffer$a82D$ FROM q;

